/usr/bin/bash -lc "mkdir -p final_answer
perl -MJSON::PP -MList::Util=sum -e '
my ("'$json_path,$fasta_path,$yaml_path,$out_path)=@ARGV;
my $json_text = do { local $/; open my $fh, "<", $json_path or die $!; <$fh> };
my $biom = decode_json($json_text);
my @cols = map { $_->{id} } @{$biom->{columns}};
my %col_idx = map { $cols[$_] => $_ } 0..$#cols;
open my $yf, "<", $yaml_path or die $!;
my @expected;
while (<$yf>) { if (/''^'"\\s*- identifier:\\s*((?:mFMT|hFMT|noFMT)_\\S+)\\s*"'$/) { push @expected, $1; } }
close $yf;
@expected == 17 or die "expected sample parse failed: ".scalar(@expected)."'"\\n\";
for my "'$s (@expected) { die "missing BIOM sample $s'"\\n\" unless exists "'$col_idx{$s}; }
my %expected_seen = map { $_ => 1 } @expected;
for my $s (@cols) { die "additional BIOM sample $s'"\\n\" unless "'$expected_seen{$s}; }
my %seq_by_id; my ($id,$seq) = (undef, "");
open my $ff, "<", $fasta_path or die $!;
while (<$ff>) { chomp; if (/''^>('"\\S+)/) { if (defined "'$id) { $seq =~ tr/acgtun/ACGTTN/; $seq_by_id{$id}=$seq; } ($id,$seq)=($1,""); } else { s/'"\\s+//g; "'$seq .= $_; } }
if (defined $id) { $seq =~ tr/acgtun/ACGTTN/; $seq_by_id{$id}=$seq; }
close $ff;
my @rows = @{$biom->{rows}};
my %row_counts; my @seq_order;
for my $ri (0..$#rows) {
  my $fid = $rows[$ri]{id};
  die "missing sequence for feature $fid'"\\n\" unless exists "'$seq_by_id{$fid};
  my $seq = $seq_by_id{$fid};
  die "invalid sequence for $fid'"\\n\" unless "'$seq =~ /''^[ACGTN]+$/;
  if (!exists $row_counts{$seq}) { $row_counts{$seq} = [(0) x @cols]; push @seq_order, $seq; }
}
for my $triple (@{$biom->{data}}) {
  my ($ri,$ci,$v) = @$triple;
  my $fid = $rows[$ri]{id};
  my $seq = $seq_by_id{$fid};
  my $iv = int($v + 0.5);
  die "non-integer count $v'"\\n\" if abs("'$v - $iv) > 1e-6;
  die "negative count $v'"\\n\" if "'$iv < 0;
  $row_counts{$seq}[$ci] += $iv;
}
open my $out, ">", $out_path or die $!;
print $out join("'"\\t\", \"sequence\", @expected), \"\\n\";
for my "'$seq (@seq_order) {
  my @counts = @{$row_counts{$seq}}[@col_idx{@expected}];
  print $out join("'"\\t\", "'$seq, @counts), "'"\\n\";
}
close "'$out;
print "rows=", scalar(@seq_order), " samples=", scalar(@expected), " total_count=", sum(map { sum(@{$row_counts{$_}}) } @seq_order), "'"\\n\";
' run_trace/galaxy_exports/feature_table.biom1.json run_trace/galaxy_exports/extracted_reps/dna-sequences.fasta codex_visible/task_input.yaml final_answer/asv_abundance.tsv
